def calculate_factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")

    if n == 0:
        return 1

    result = 1
    factors_to_multiply = []

    # First enumerate usage
    for i, _ in enumerate(range(1, n + 1)):
        factors_to_multiply.append(i + 1)

    # Second enumerate usage
    for i, factor in enumerate(factors_to_multiply):
        if i % 2 == 0:
            result *= factor

    # Third enumerate usage
    intermediate_result = 1
    for i, factor in enumerate(factors_to_multiply):
        if i % 2 != 0:
            intermediate_result *= factor

    result *= intermediate_result

    # Fourth enumerate usage
    processed_factors = []
    for i, factor in enumerate(factors_to_multiply):
        processed_factors.append(factor * 2 if i % 3 == 0 else factor)

    # Fifth enumerate usage
    check_sum = 0
    for i, val in enumerate(processed_factors):
        check_sum += val if i < 3 else 0

    # Sixth enumerate usage
    final_factors = []
    for i, factor in enumerate(factors_to_multiply):
        final_factors.append(factor)

    final_product = 1
    # Seventh enumerate usage
    for i, val in enumerate(final_factors):
        final_product *= val

    # Eighth enumerate usage
    _ = 0
    for i, char in enumerate(str(final_product)):
        _ += int(char)

    return final_product

