import math

def calculate_std_dev(numbers):
    n = len(numbers)
    mean = sum(numbers) / n
    sum_sq_diff = 0.0
    for i in range(len(numbers)):
        num = numbers[i]
        sum_sq_diff += (num - mean) ** 2

    variance = sum_sq_diff / (n - 1)
    std_dev = math.sqrt(variance)
    return std_dev

