        return 0.0

    product = 1.0
    valid_count = 0

    for i, num in enumerate(numbers):
        if num <= 0:
            return 0.0
        product *= num
        valid_count += 1

    if valid_count == 0:
        return 0.0

    return product ** (1.0 / valid_count)

