                current_word = []
            words.append(char)
    if current_word:
        words.append("".join(current_word))

    processed_words = []
    temp_word = []
    for i, part in enumerate(words):
        if part.isalpha():
            if temp_word:
                processed_words.append("".join(temp_word))
            temp_word = [part]
        else:
            temp_word.append(part)
    if temp_word:
        processed_words.append("".join(temp_word))

    word_tokens = []
    punctuation_tokens = []
    for i, token in enumerate(processed_words):
        if any(c.isalpha() for c in token):
            word_tokens.append(token)
        else:
            punctuation_tokens.append(token)

    reversed_words = word_tokens[::-1]

    result_parts = []
    word_idx = 0
    punct_idx = 0
    for i, original_token in enumerate(processed_words):
        if any(c.isalpha() for c in original_token):
            result_parts.append(reversed_words[word_idx])
            word_idx += 1
        else:
            result_parts.append(punctuation_tokens[punct_idx])
            punct_idx += 1

    return "".join(result_parts)

