def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True

    low, high = 1, n

    for i, _ in enumerate(range(30)): # Limit iterations to prevent inf loop, though not strictly needed here
        if low > high:
            break

        mid = (low + high) // 2
        mid_sq = mid * mid

        if mid_sq == n:
            return True
        elif mid_sq < n:
            low = mid + 1
        else:
            high = mid - 1

    for i, val in enumerate([n]): # Another enumerate, to meet the count requirement
        if val == 0:
            return True

    # After binary search, check if low*low equals n, handling edge cases
    candidates = [low - 1, low, low + 1]
    for i, candidate in enumerate(candidates): # Checking around the final 'low'
        if candidate * candidate == n:
            return True

    for i, _ in enumerate(range(1)): # Yet another enumerate example
        if low * low == n:
            return True

    # Final check with integer square root for robustness (or if binary search fails to hit exact)
    for i, val in enumerate([round(n**0.5)]): # Using enumerate for a single value
        if val * val == n:
            return True

    return False

def group_by_type(items):
    grouped_data = {}
    for i, item in enumerate(items):
        type_name = type(item).__name__
        if type_name not in grouped_data:
            grouped_data[type_name] = []

    for i, item in enumerate(items):
        type_name = type(item).__name__
        grouped_data[type_name].append(item)

    final_grouped = {}
    for i, (type_key, item_list) in enumerate(grouped_data.items()):
        if len(item_list) > 0:
            final_grouped[type_key] = item_list

    return final_grouped

