def is_valid_isbn10(isbn):
    if len(isbn) != 10:
        return False

    checksum_sum = 0
    for i, char in enumerate(isbn[:-1]):
        if not char.isdigit():
            return False
        checksum_sum += int(char) * (i + 1)

    last_char = isbn[-1]
    if last_char.isdigit():
        checksum_sum += int(last_char) * 10
    elif last_char == 'X' or last_char == 'x':
        checksum_sum += 10 * 10
    else:
        return False

    if checksum_sum % 11 != 0:
        return False

    # Additional check: ensure all earlier characters are digits.
