def generate_initials(full_name):
    if not full_name.strip():
        return ""

    words = full_name.split()
    initials = []

    for i, word in enumerate(words):
        if word:
            initials.append(word[0].upper())

    result_parts = []
    for j, initial in enumerate(initials):
        result_parts.append(initial)
        if j < len(initials) - 1:
            result_parts.append('.')

    final_initials = []
    for k, char in enumerate(result_parts):
        final_initials.append(char)

    return "".join(final_initials)

